package com.actualafk;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("afkmastery")
public interface AfkConfig extends Config
{
	String CONFIG_GROUP = "afkmastery";
	String MINIMUM_IDLE_TICKS_KEY = "minimumIdleTicks";
	String ACTIVITY_GRACE_TICKS_KEY = "activityGraceTicks";
	String SHOW_CANVAS_OVERLAY_KEY = "showCanvasOverlay";
	String SHOW_PANEL_STATISTIC_KEY_PREFIX = "showPanel";
	String SHOW_SIDEBAR_STATISTIC_KEY_PREFIX = "showSidebar";

	@ConfigItem(
		keyName = "trackingEnabled",
		name = "Enable tracking",
		description = "Track AFK time",
		position = 0
	)
	default boolean trackingEnabled()
	{
		return true;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(
		keyName = MINIMUM_IDLE_TICKS_KEY,
		name = "Minimum inactive ticks",
		description = "Consecutive inactive game ticks needed before AFK time starts counting",
		position = 1
	)
	default int minimumIdleTicks()
	{
		return 1;
	}

	@Range(min = 0, max = 20)
	@ConfigItem(
		keyName = ACTIVITY_GRACE_TICKS_KEY,
		name = "Activity grace ticks",
		description = "Ticks after observed animation, interaction, or incoming combat during which AFK time is not counted",
		position = 2
	)
	default int activityGraceTicks()
	{
		return 1;
	}

	@ConfigItem(
		keyName = SHOW_CANVAS_OVERLAY_KEY,
		name = "Show canvas overlay",
		description = "Show AFK progress on the RuneLite canvas",
		position = 3
	)
	default boolean showCanvasOverlay()
	{
		return false;
	}

	@ConfigItem(keyName = "showSidebarTotalAfkXp", name = "Show total AFK XP", description = "Show total client-side AFK XP in the detailed statistics", position = 4)
	default boolean showPanelTotalAfkXp() { return true; }

	@ConfigItem(keyName = "showPanelCurrentStreakTicks", name = "Show current streak ticks", description = "Show current inactive streak ticks in the detailed statistics", position = 6)
	default boolean showPanelCurrentStreakTicks() { return true; }

	@ConfigItem(keyName = "showPanelCurrentStreakTime", name = "Show current streak time", description = "Show estimated current inactive streak time in the RuneLite plugin panel", position = 8)
	default boolean showPanelCurrentStreakTime() { return true; }

	@ConfigItem(keyName = "showPanelLongestStreakTicks", name = "Show longest streak ticks", description = "Show longest inactive streak ticks in the RuneLite plugin panel", position = 9)
	default boolean showPanelLongestStreakTicks() { return true; }

	@ConfigItem(keyName = "showPanelLongestStreakTime", name = "Show longest streak time", description = "Show estimated longest inactive streak time in the RuneLite plugin panel", position = 10)
	default boolean showPanelLongestStreakTime() { return true; }

	@ConfigItem(keyName = "showPanelSessionAfkTicks", name = "Show session AFK ticks", description = "Show session AFK ticks in the RuneLite plugin panel", position = 11)
	default boolean showPanelSessionAfkTicks() { return true; }

	@ConfigItem(keyName = "showPanelSessionAfkTime", name = "Show session AFK time", description = "Show estimated session AFK time in the RuneLite plugin panel", position = 12)
	default boolean showPanelSessionAfkTime() { return true; }

	@ConfigItem(keyName = "showPanelSessionTotalTime", name = "Show session total time", description = "Show estimated session total time in the RuneLite plugin panel", position = 13)
	default boolean showPanelSessionTotalTime() { return true; }

	@ConfigItem(keyName = "showPanelSessionIdlePercentage", name = "Show session idle %", description = "Show session idle percentage in the RuneLite plugin panel", position = 14)
	default boolean showPanelSessionIdlePercentage() { return true; }

	@ConfigItem(keyName = "showPanelSessionActivePercentage", name = "Show session active %", description = "Show session active percentage in the RuneLite plugin panel", position = 15)
	default boolean showPanelSessionActivePercentage() { return true; }

	@ConfigItem(keyName = "showPanelSessionAfkXp", name = "Show session AFK XP", description = "Show session AFK XP", position = 16)
	default boolean showPanelSessionAfkXp() { return true; }

	@ConfigItem(keyName = "showSidebarSessionXpPerHour", name = "Show session XP/hr", description = "Show session AFK XP per hour", position = 17)
	default boolean showPanelSessionXpPerHour() { return true; }

	@ConfigItem(keyName = "showPanelTotalAfkTicks", name = "Show total AFK ticks", description = "Show total AFK ticks in the RuneLite plugin panel", position = 18)
	default boolean showPanelTotalAfkTicks() { return true; }

	@ConfigItem(keyName = "showPanelTotalTime", name = "Show total time", description = "Show estimated total time in the RuneLite plugin panel", position = 19)
	default boolean showPanelTotalTime() { return true; }

	@ConfigItem(keyName = "showPanelTotalIdlePercentage", name = "Show total idle %", description = "Show total idle percentage in the RuneLite plugin panel", position = 20)
	default boolean showPanelTotalIdlePercentage() { return true; }

	@ConfigItem(keyName = "showPanelTotalActivePercentage", name = "Show total active %", description = "Show total active percentage in the RuneLite plugin panel", position = 21)
	default boolean showPanelTotalActivePercentage() { return true; }

	@ConfigItem(keyName = "showPanelXpToNextLevel", name = "Show XP to next level", description = "Show AFK XP needed for the next level", position = 22)
	default boolean showPanelXpToNextLevel() { return true; }
}

package com.actualafk;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import com.google.inject.Provides;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Actual AFK",
	description = "Track your AFK time and progress.",
	tags = {"afk", "tracker", "time"})
public class AfkPlugin extends Plugin
{
	private static final int SAVE_BATCH_SIZE = 10;

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AfkConfig config;

	@Inject
	private ProgressPanel panel;

	@Inject
	private OverlayManager overlayManager;

	private NavigationButton navigationButton;
	private ProgressStore progressStore;
	private AfkProgress afkProgress;
	private IdleTracker idleActivityTracker;
	private ProgressOverlay canvasOverlay;
	private boolean canvasOverlayAdded;
	private boolean activitySignalPending;
	private boolean progressLoadedForProfile;
	private int observedTicksSinceSave;
	private int lastProcessedTickCount = Integer.MIN_VALUE;
	private boolean started;
	private ProgressSnapshot lastDisplayedSnapshot;
	private long sessionObservedTicks;

	@Provides
	AfkConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AfkConfig.class);
	}

	@Override
	protected void startUp()
	{
		if (started)
		{
			return;
		}

		started = true;
		progressStore = new ProgressStore(configManager);
		afkProgress = new AfkProgress();
		progressLoadedForProfile = false;
		idleActivityTracker = createIdleTracker();
		activitySignalPending = false;
		observedTicksSinceSave = 0;
		lastProcessedTickCount = Integer.MIN_VALUE;
		panel.resetSessionTiming();
		lastDisplayedSnapshot = null;
		sessionObservedTicks = 0;
		panel.setResetAction(this::resetLocalProgress);
		panel.setCanvasOverlayToggleAction(this::setCanvasOverlayEnabled);
		loadProgressForCurrentProfile();
		canvasOverlay = new ProgressOverlay(this, loadClockIcon());
		applyCanvasOverlayEnabled(config.showCanvasOverlay());

		navigationButton = NavigationButton.builder()
			.icon(loadClockIcon())
			.tooltip("Actual AFK")
			.onClick(() -> clientToolbar.openPanel(navigationButton))
			.panel(panel)
			.priority(10)
			.build();
		clientToolbar.addNavigation(navigationButton);
		refreshPanel(currentDisplayState());
	}

	@Override
	protected void shutDown()
	{
		if (!started)
		{
			return;
		}

		if (progressLoadedForProfile && progressStore != null && afkProgress != null)
		{
			progressStore.save(afkProgress);
		}
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}
		removeCanvasOverlay();

		started = false;
		progressLoadedForProfile = false;
		activitySignalPending = false;
		observedTicksSinceSave = 0;
		lastProcessedTickCount = Integer.MIN_VALUE;
		navigationButton = null;
		progressStore = null;
		afkProgress = null;
		idleActivityTracker = null;
		canvasOverlay = null;
		panel.setResetAction(() ->
		{
		});
		panel.setCanvasOverlayToggleAction(enabled ->
		{
		});
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!started)
		{
			return;
		}
		if (!beginGameTick(client.getTickCount()))
		{
			return;
		}
		if (!progressLoadedForProfile)
		{
			loadProgressForCurrentProfile();
			if (!progressLoadedForProfile)
			{
				refreshPanel(currentDisplayState());
				return;
			}
		}

		if (!config.trackingEnabled())
		{
			idleActivityTracker.reset();
			afkProgress.setCurrentIdleStreakTicks(0);
			activitySignalPending = false;
			refreshPanel(IdleTracker.TickState.PAUSED);
			return;
		}
		if (!progressStore.canSave())
		{
			idleActivityTracker.reset();
			afkProgress.setCurrentIdleStreakTicks(0);
			activitySignalPending = false;
			refreshPanel(IdleTracker.TickState.PAUSED);
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		if (loggedIn && localPlayer != null)
		{
			sessionObservedTicks++;
			afkProgress.addObservedTick();
			observedTicksSinceSave++;
		}
		IdleTracker.TickObservation observation =
			IdleTracker.TickObservation.withActivitySignals(
			loggedIn,
			localPlayer != null,
			localPlayer == null ? null : localPlayer.getWorldLocation(),
			localPlayer == null ? null : localPlayer.getAnimation() != -1,
			localPlayer == null ? null : localPlayer.getInteracting() != null,
			activitySignalPending,
			false,
			false,
			false);
		activitySignalPending = false;

		IdleTracker.TickResult result = idleActivityTracker.observe(observation);
		afkProgress.setCurrentIdleStreakTicks(result.currentStreakTicks());
		if (result.qualifies())
		{
			afkProgress.addQualifyingTick(result.currentStreakTicks());
		}
		if (observedTicksSinceSave >= SAVE_BATCH_SIZE)
		{
			progressStore.save(afkProgress);
			observedTicksSinceSave = 0;
		}

		refreshPanel(result.currentState());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!started || !AfkConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (AfkConfig.SHOW_CANVAS_OVERLAY_KEY.equals(event.getKey()))
		{
			applyCanvasOverlayEnabled(config.showCanvasOverlay());
		}
		else if (event.getKey().startsWith(AfkConfig.SHOW_PANEL_STATISTIC_KEY_PREFIX)
			|| event.getKey().startsWith(AfkConfig.SHOW_SIDEBAR_STATISTIC_KEY_PREFIX))
		{
			panel.refreshStatisticVisibility();
		}
		else if (AfkConfig.MINIMUM_IDLE_TICKS_KEY.equals(event.getKey())
			|| AfkConfig.ACTIVITY_GRACE_TICKS_KEY.equals(event.getKey()))
		{
			idleActivityTracker = createIdleTracker();
			afkProgress.setCurrentIdleStreakTicks(0);
			activitySignalPending = false;
			lastProcessedTickCount = Integer.MIN_VALUE;
			refreshPanel(currentDisplayState());
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		if (!started)
		{
			return;
		}

		if (progressLoadedForProfile && progressStore != null && afkProgress != null
			&& event.getPreviousProfile() != null)
		{
			progressStore.save(afkProgress, event.getPreviousProfile());
		}
		progressLoadedForProfile = false;
		afkProgress = new AfkProgress();
		sessionObservedTicks = 0;
		activitySignalPending = false;
		lastDisplayedSnapshot = null;
		panel.resetSessionTiming();
		loadProgressForCurrentProfile();
		refreshPanel(currentDisplayState());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (!started)
		{
			return;
		}
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadProgressForCurrentProfile();
			return;
		}

		idleActivityTracker.reset();
		lastProcessedTickCount = Integer.MIN_VALUE;
		afkProgress.setCurrentIdleStreakTicks(0);
		activitySignalPending = false;
		if (progressLoadedForProfile)
		{
			progressStore.save(afkProgress);
		}
		observedTicksSinceSave = 0;
		refreshPanel(displayStateFor(event.getGameState()));
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (started && isLocalPlayer(event.getActor()))
		{
			markActivityGrace();
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (started && (isLocalPlayer(event.getSource()) || isLocalPlayer(event.getTarget())))
		{
			markActivityGrace();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		// HitsplatApplied's actor is the actor receiving the hit. Only incoming
		// hitsplats are relevant; outgoing damage must not suppress AFK tracking.
		if (started && isLocalPlayer(event.getActor()))
		{
			markActivityGrace();
		}
	}

	private void markActivityGrace()
	{
		activitySignalPending = true;
	}

	private IdleTracker createIdleTracker()
	{
		return new IdleTracker(config.minimumIdleTicks(), config.activityGraceTicks());
	}

	private boolean isLocalPlayer(Actor actor)
	{
		return actor != null && actor == client.getLocalPlayer();
	}

	boolean beginGameTick(int tickCount)
	{
		if (tickCount == lastProcessedTickCount)
		{
			return false;
		}
		lastProcessedTickCount = tickCount;
		return true;
	}

	private void resetLocalProgress()
	{
		if (!started || clientThread == null)
		{
			return;
		}
		clientThread.invoke(this::resetLocalProgressOnClientThread);
	}

	private void resetLocalProgressOnClientThread()
	{
		if (!started || !progressLoadedForProfile || progressStore == null || afkProgress == null)
		{
			return;
		}

		afkProgress.reset();
		sessionObservedTicks = 0;
		idleActivityTracker.reset();
		activitySignalPending = false;
		observedTicksSinceSave = 0;
		lastDisplayedSnapshot = null;
		panel.resetSessionTiming();
		progressStore.reset();
		refreshPanel(currentDisplayState());
	}

	private void loadProgressForCurrentProfile()
	{
		if (progressLoadedForProfile || progressStore == null || !progressStore.isAvailable())
		{
			return;
		}

		afkProgress = progressStore.load();
		progressLoadedForProfile = true;
		idleActivityTracker.reset();
		activitySignalPending = false;
		observedTicksSinceSave = 0;
	}

	private void setCanvasOverlayEnabled(boolean enabled)
	{
		if (!started)
		{
			return;
		}

		if (config.showCanvasOverlay() != enabled)
		{
			configManager.setConfiguration(
				AfkConfig.CONFIG_GROUP,
				AfkConfig.SHOW_CANVAS_OVERLAY_KEY,
				enabled);
		}
		applyCanvasOverlayEnabled(enabled);
	}

	private void applyCanvasOverlayEnabled(boolean enabled)
	{
		if (!started || canvasOverlay == null)
		{
			return;
		}

		if (enabled && !canvasOverlayAdded)
		{
			overlayManager.add(canvasOverlay);
			canvasOverlayAdded = true;
		}
		else if (!enabled)
		{
			removeCanvasOverlay();
		}
		if (panel != null)
		{
			panel.setCanvasOverlayVisible(enabled);
		}
	}

	private void removeCanvasOverlay()
	{
		if (canvasOverlayAdded && canvasOverlay != null)
		{
			overlayManager.remove(canvasOverlay);
		}
		canvasOverlayAdded = false;
		if (panel != null)
		{
			panel.setCanvasOverlayVisible(false);
		}
	}

	private void refreshPanel(IdleTracker.TickState state)
	{
		if (panel == null || afkProgress == null)
		{
			return;
		}

		ProgressSnapshot snapshot = new ProgressSnapshot(
			afkProgress.getAfkLevel(),
			afkProgress.getTotalAfkXp(),
			afkProgress.getCurrentLevelXp(),
			afkProgress.getNextLevelXp(),
			afkProgress.getCurrentIdleStreakTicks(),
			afkProgress.getLongestIdleStreakTicks(),
			afkProgress.getSessionQualifyingTicks(),
			sessionObservedTicks,
			afkProgress.getTotalObservedTicks(),
			stateText(state));
		if (canvasOverlay != null)
		{
			canvasOverlay.updateDisplayedValues(snapshot);
		}
		if (snapshot.equals(lastDisplayedSnapshot))
		{
			return;
		}

		lastDisplayedSnapshot = snapshot;
		panel.updateDisplayedValues(snapshot);
	}

	private IdleTracker.TickState currentDisplayState()
	{
		if (client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null)
		{
			return IdleTracker.TickState.ACTIVE;
		}
		return displayStateFor(client.getGameState());
	}

	private IdleTracker.TickState displayStateFor(GameState gameState)
	{
		if (gameState == GameState.LOADING || gameState == GameState.HOPPING || gameState == GameState.STARTING)
		{
			return IdleTracker.TickState.PAUSED;
		}
		return IdleTracker.TickState.LOGGED_OUT;
	}

	private String stateText(IdleTracker.TickState state)
	{
		switch (state)
		{
			case INACTIVE:
				return "Inactive";
			case PENDING:
				return "Pending";
			case PAUSED:
				return "Paused";
			case LOGGED_OUT:
				return "Logged out";
			case ACTIVE:
			default:
				return "Active";
		}
	}

	private BufferedImage loadClockIcon()
	{
		try (InputStream inputStream = AfkPlugin.class.getResourceAsStream(
			"/com/actualafk/icon.png"))
		{
			if (inputStream == null)
			{
				return new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
			}
			BufferedImage image = ImageIO.read(inputStream);
			if (image == null)
			{
				return new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
			}
			BufferedImage resized = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
			java.awt.Graphics2D graphics = resized.createGraphics();
			try
			{
				graphics.setRenderingHint(
					java.awt.RenderingHints.KEY_INTERPOLATION,
					java.awt.RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				graphics.drawImage(image, 0, 0, 16, 16, null);
			}
			finally
			{
				graphics.dispose();
			}
			return resized;
		}
		catch (IOException exception)
		{
			return new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		}
	}

}

package com.actualafk;

public final class AfkProgress
{
	private static final int MAXIMUM_LEVEL = 99;
	private static final long[] EXPERIENCE_FOR_LEVEL = createExperienceTable();

	private long totalAfkXp;
	private long currentIdleStreakTicks;
	private long longestIdleStreakTicks;
	private long sessionQualifyingTicks;
	private long totalObservedTicks;

	public AfkProgress()
	{
	}

	public AfkProgress(long totalAfkXp, long currentIdleStreakTicks,
		long longestIdleStreakTicks, long sessionQualifyingTicks)
	{
		this(totalAfkXp, currentIdleStreakTicks, longestIdleStreakTicks,
			sessionQualifyingTicks, totalAfkXp);
	}

	public AfkProgress(long totalAfkXp, long currentIdleStreakTicks,
		long longestIdleStreakTicks, long sessionQualifyingTicks, long totalObservedTicks)
	{
		this.totalAfkXp = nonNegative(totalAfkXp);
		this.currentIdleStreakTicks = nonNegative(currentIdleStreakTicks);
		this.longestIdleStreakTicks = nonNegative(longestIdleStreakTicks);
		this.sessionQualifyingTicks = nonNegative(sessionQualifyingTicks);
		this.totalObservedTicks = Math.max(this.totalAfkXp, nonNegative(totalObservedTicks));
		if (this.longestIdleStreakTicks < this.currentIdleStreakTicks)
		{
			this.longestIdleStreakTicks = this.currentIdleStreakTicks;
		}
	}

	public void addObservedTick()
	{
		totalObservedTicks = incrementSaturated(totalObservedTicks);
	}

	public void addQualifyingTick()
	{
		addQualifyingTick(incrementSaturated(currentIdleStreakTicks));
	}

	public void addQualifyingTick(long currentIdleStreakTicks)
	{
		this.currentIdleStreakTicks = nonNegative(currentIdleStreakTicks);
		this.totalAfkXp = incrementSaturated(this.totalAfkXp);
		this.sessionQualifyingTicks = incrementSaturated(this.sessionQualifyingTicks);
		if (this.currentIdleStreakTicks > longestIdleStreakTicks)
		{
			longestIdleStreakTicks = this.currentIdleStreakTicks;
		}
	}

	public void setCurrentIdleStreakTicks(long currentIdleStreakTicks)
	{
		this.currentIdleStreakTicks = nonNegative(currentIdleStreakTicks);
	}

	public void reset()
	{
		totalAfkXp = 0;
		currentIdleStreakTicks = 0;
		longestIdleStreakTicks = 0;
		sessionQualifyingTicks = 0;
		totalObservedTicks = 0;
	}

	public long getTotalAfkXp()
	{
		return totalAfkXp;
	}

	public long getCurrentIdleStreakTicks()
	{
		return currentIdleStreakTicks;
	}

	public long getLongestIdleStreakTicks()
	{
		return longestIdleStreakTicks;
	}

	public long getSessionQualifyingTicks()
	{
		return sessionQualifyingTicks;
	}

	public long getTotalObservedTicks()
	{
		return totalObservedTicks;
	}

	public int getAfkLevel()
	{
		for (int level = MAXIMUM_LEVEL; level > 1; level--)
		{
			if (totalAfkXp >= EXPERIENCE_FOR_LEVEL[level])
			{
				return level;
			}
		}
		return 1;
	}

	public long getCurrentLevelXp()
	{
		return EXPERIENCE_FOR_LEVEL[getAfkLevel()];
	}

	public long getNextLevelXp()
	{
		int level = getAfkLevel();
		return EXPERIENCE_FOR_LEVEL[Math.min(level + 1, MAXIMUM_LEVEL)];
	}

	public long getXpToNextLevel()
	{
		return Math.max(0, getNextLevelXp() - totalAfkXp);
	}

	public static long getExperienceForLevel(int level)
	{
		if (level < 1 || level > MAXIMUM_LEVEL)
		{
			throw new IllegalArgumentException("level must be between 1 and 99");
		}
		return EXPERIENCE_FOR_LEVEL[level];
	}

	private static long[] createExperienceTable()
	{
		long[] experienceForLevel = new long[MAXIMUM_LEVEL + 1];
		long cumulativePoints = 0;
		for (int level = 1; level < MAXIMUM_LEVEL; level++)
		{
			cumulativePoints += (long) (level + 300 * Math.pow(2, level / 7.0));
			experienceForLevel[level + 1] = cumulativePoints / 4;
		}
		return experienceForLevel;
	}

	private static long nonNegative(long value)
	{
		return Math.max(0, value);
	}

	private static long incrementSaturated(long value)
	{
		return value == Long.MAX_VALUE ? Long.MAX_VALUE : value + 1;
	}
}

package com.actualafk;

import java.util.Objects;

public final class IdleTracker
{
	private final int minimumIdleTicks;
	private final int activityGraceTicks;
	private Object previousLocation;
	private int pendingInactiveTicks;
	private int currentStreakTicks;
	private int remainingActivityGraceTicks;
	private TickObservation lastObservation;
	private TickResult lastResult = TickResult.initial();

	public IdleTracker(int minimumIdleTicks)
	{
		this(minimumIdleTicks, 0);
	}

	/**
	 * Creates a tracker with an exact trailing grace window. An observation with
	 * a known activity signal is active itself and keeps the following
	 * {@code activityGraceTicks} observations active. Pending observations are
	 * never converted into qualifying observations when the window expires.
	 */
	public IdleTracker(int minimumIdleTicks, int activityGraceTicks)
	{
		this.minimumIdleTicks = Math.max(1, minimumIdleTicks);
		this.activityGraceTicks = Math.max(0, activityGraceTicks);
	}

	public TickResult observe(TickObservation observation)
	{
		Objects.requireNonNull(observation, "observation");
		if (observation == lastObservation)
		{
			return lastResult;
		}
		lastObservation = observation;

		if (!Boolean.TRUE.equals(observation.loggedIn()))
		{
			return reset(TickState.LOGGED_OUT);
		}

		if (!Boolean.TRUE.equals(observation.playerAvailable()) || observation.location() == null)
		{
			return reset(TickState.PAUSED);
		}

		if (previousLocation == null)
		{
			previousLocation = observation.location();
			if (hasKnownActivitySignal(observation))
			{
				startActivityGrace();
			}
			return resetResult(TickState.ACTIVE);
		}

		boolean locationChanged = !Objects.equals(previousLocation, observation.location());
		previousLocation = observation.location();

		if (locationChanged)
		{
			startActivityGrace();
			return activeResult();
		}

		if (!isInactiveObservation(observation))
		{
			if (hasKnownActivitySignal(observation))
			{
				startActivityGrace();
			}
			else if (remainingActivityGraceTicks > 0)
			{
				remainingActivityGraceTicks--;
			}
			return activeResult();
		}

		if (remainingActivityGraceTicks > 0)
		{
			remainingActivityGraceTicks--;
			return activeResult();
		}

		if (pendingInactiveTicks < Integer.MAX_VALUE)
		{
			pendingInactiveTicks++;
		}
		if (pendingInactiveTicks < minimumIdleTicks)
		{
			lastResult = new TickResult(false, currentStreakTicks, TickState.PENDING);
			return lastResult;
		}

		if (currentStreakTicks < Integer.MAX_VALUE)
		{
			currentStreakTicks++;
		}
		lastResult = new TickResult(true, currentStreakTicks, TickState.INACTIVE);
		return lastResult;
	}

	public TickResult getLastResult()
	{
		return lastResult;
	}

	public int getMinimumIdleTicks()
	{
		return minimumIdleTicks;
	}

	public int getActivityGraceTicks()
	{
		return activityGraceTicks;
	}

	public int getRemainingActivityGraceTicks()
	{
		return remainingActivityGraceTicks;
	}

	public int getPendingInactiveTicks()
	{
		return pendingInactiveTicks;
	}

	public int getCurrentStreakTicks()
	{
		return currentStreakTicks;
	}

	public void reset()
	{
		previousLocation = null;
		pendingInactiveTicks = 0;
		currentStreakTicks = 0;
		remainingActivityGraceTicks = 0;
		lastObservation = null;
		lastResult = TickResult.initial();
	}

	private boolean isInactiveObservation(TickObservation observation)
	{
		return Boolean.FALSE.equals(observation.animationActive())
			&& Boolean.FALSE.equals(observation.interactionActive())
			&& Boolean.FALSE.equals(observation.activityGrace())
			&& Boolean.FALSE.equals(observation.combatActive())
			&& Boolean.FALSE.equals(observation.hitsplatActive())
			&& Boolean.FALSE.equals(observation.trackedActionGrace());
	}

	private boolean hasKnownActivitySignal(TickObservation observation)
	{
		return Boolean.TRUE.equals(observation.animationActive())
			|| Boolean.TRUE.equals(observation.interactionActive())
			|| Boolean.TRUE.equals(observation.activityGrace())
			|| Boolean.TRUE.equals(observation.combatActive())
			|| Boolean.TRUE.equals(observation.hitsplatActive())
			|| Boolean.TRUE.equals(observation.trackedActionGrace());
	}

	private void startActivityGrace()
	{
		remainingActivityGraceTicks = activityGraceTicks;
	}

	private TickResult activeResult()
	{
		pendingInactiveTicks = 0;
		currentStreakTicks = 0;
		lastResult = new TickResult(false, 0, TickState.ACTIVE);
		return lastResult;
	}

	private TickResult reset(TickState state)
	{
		reset();
		lastResult = new TickResult(false, 0, state);
		return lastResult;
	}

	private TickResult resetResult(TickState state)
	{
		pendingInactiveTicks = 0;
		currentStreakTicks = 0;
		lastResult = new TickResult(false, 0, state);
		return lastResult;
	}

	public enum TickState
	{
		INACTIVE,
		PENDING,
		ACTIVE,
		PAUSED,
		LOGGED_OUT
	}

	public static final class TickObservation
	{
		private final Boolean loggedIn;
		private final Boolean playerAvailable;
		private final Object location;
		private final Boolean animationActive;
		private final Boolean interactionActive;
		private final Boolean activityGrace;
		private final Boolean combatActive;
		private final Boolean hitsplatActive;
		private final Boolean trackedActionGrace;

		public TickObservation(
			Boolean loggedIn,
			Boolean playerAvailable,
			Object location,
			Boolean animationActive,
			Boolean interactionActive,
			Boolean activityGrace)
		{
			this.loggedIn = loggedIn;
			this.playerAvailable = playerAvailable;
			this.location = location;
			this.animationActive = animationActive;
			this.interactionActive = interactionActive;
			this.activityGrace = activityGrace;
			this.combatActive = false;
			this.hitsplatActive = false;
			this.trackedActionGrace = false;
		}

		private TickObservation(
			Boolean loggedIn,
			Boolean playerAvailable,
			Object location,
			Boolean animationActive,
			Boolean interactionActive,
			Boolean activityGrace,
			Boolean combatActive,
			Boolean hitsplatActive,
			Boolean trackedActionGrace)
		{
			this.loggedIn = loggedIn;
			this.playerAvailable = playerAvailable;
			this.location = location;
			this.animationActive = animationActive;
			this.interactionActive = interactionActive;
			this.activityGrace = activityGrace;
			this.combatActive = combatActive;
			this.hitsplatActive = hitsplatActive;
			this.trackedActionGrace = trackedActionGrace;
		}

		/**
		 * Creates an observation with the activity signals that require
		 * conservative classification. A null signal is unknown and therefore
		 * makes the observation active, just like the legacy fields.
		 */
		public static TickObservation withActivitySignals(
			Boolean loggedIn,
			Boolean playerAvailable,
			Object location,
			Boolean animationActive,
			Boolean interactionActive,
			Boolean activityGrace,
			Boolean combatActive,
			Boolean hitsplatActive,
			Boolean trackedActionGrace)
		{
			return new TickObservation(
				loggedIn,
				playerAvailable,
				location,
				animationActive,
				interactionActive,
				activityGrace,
				combatActive,
				hitsplatActive,
				trackedActionGrace);
		}

		public Boolean loggedIn()
		{
			return loggedIn;
		}

		public Boolean playerAvailable()
		{
			return playerAvailable;
		}

		public Object location()
		{
			return location;
		}

		public Boolean animationActive()
		{
			return animationActive;
		}

		public Boolean interactionActive()
		{
			return interactionActive;
		}

		public Boolean activityGrace()
		{
			return activityGrace;
		}

		public Boolean combatActive()
		{
			return combatActive;
		}

		public Boolean hitsplatActive()
		{
			return hitsplatActive;
		}

		public Boolean trackedActionGrace()
		{
			return trackedActionGrace;
		}
	}

	public static final class TickResult
	{
		private final boolean qualifies;
		private final int currentStreakTicks;
		private final TickState currentState;

		public TickResult(boolean qualifies, int currentStreakTicks, TickState currentState)
		{
			this.qualifies = qualifies;
			this.currentStreakTicks = currentStreakTicks;
			this.currentState = Objects.requireNonNull(currentState, "currentState");
		}

		public boolean qualifies()
		{
			return qualifies;
		}

		public int currentStreakTicks()
		{
			return currentStreakTicks;
		}

		public TickState currentState()
		{
			return currentState;
		}

		private static TickResult initial()
		{
			return new TickResult(false, 0, TickState.PAUSED);
		}
	}
}

