public class ProgressOverlayTest
{
	@Test
	public void progressPercentageUsesCurrentAfkLevelRange()
	{
		assertEquals(0, ProgressOverlay.calculateProgressPercentage(83, 83, 174));
		assertEquals(50, ProgressOverlay.calculateProgressPercentage(128, 83, 173));
		assertEquals(100, ProgressOverlay.calculateProgressPercentage(200, 83, 173));
		assertEquals(100, ProgressOverlay.calculateProgressPercentage(13034431, 13034431, 13034431));
	}

	@Test
	public void inactiveStateUsesMutedDarkOrangeBackground()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		ProgressOverlay overlay = new ProgressOverlay(null, icon);

		overlay.updateDisplayedValues(1, 0, 0, 83, 0, "Active");
		render(overlay);
		assertEquals(ComponentConstants.STANDARD_BACKGROUND_COLOR, overlay.getBackgroundColor());

		overlay.updateDisplayedValues(1, 1, 0, 83, 1, "Inactive");
		render(overlay);
		assertEquals(new java.awt.Color(92, 64, 32, 190), overlay.getBackgroundColor());
	}

	@Test
	public void persistentOverlayRendersWithStandardPlacementBehavior()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		ProgressOverlay overlay = new ProgressOverlay(null, icon);
		overlay.updateDisplayedValues(2, 100, 83, 174, 100, "Inactive");

		BufferedImage canvas = new BufferedImage(300, 120, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		Dimension renderedSize;
		try
		{
			renderedSize = overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}

		assertTrue(renderedSize.width > 0);
		assertTrue(renderedSize.height > 0);
		assertTrue(renderedSize.height <= 45);
		assertEquals(OverlayPosition.TOP_LEFT, overlay.getPosition());
		assertTrue(overlay.isMovable());
		assertTrue(overlay.isSnappable());
		assertFalse(overlay.isResizable());
	}

	@Test
	public void experiencePerHourUsesQualifyingXpOverEntireElapsedSession()
	{
		long tenSeconds = 10_000_000_000L;
		assertEquals(0, ProgressOverlay.calculateExperiencePerHour(0, tenSeconds));
		assertEquals(6000, ProgressOverlay.calculateExperiencePerHour(10, 6_000_000_000L));
		assertEquals(3000, ProgressOverlay.calculateExperiencePerHour(5, 6_000_000_000L));
		assertEquals(0, ProgressOverlay.calculateExperiencePerHour(10, 0));
	}

	@Test
	public void sessionAfkTimeUsesCompactSecondMinuteAndHourUnits()
	{
		assertEquals("0s", ProgressOverlay.formatSessionAfkTime(0));
		assertEquals("59s", ProgressOverlay.formatSessionAfkTime(99));
		assertEquals("1m", ProgressOverlay.formatSessionAfkTime(100));
		assertEquals("1m1s", ProgressOverlay.formatSessionAfkTime(102));
		assertEquals("59m59s", ProgressOverlay.formatSessionAfkTime(5_999));
		assertEquals("1h", ProgressOverlay.formatSessionAfkTime(6_000));
		assertEquals("1h", ProgressOverlay.formatSessionAfkTime(6_002));
		assertEquals("1h1m", ProgressOverlay.formatSessionAfkTime(6_102));
		assertEquals("0s", ProgressOverlay.formatSessionAfkTime(-1));
	}

	private static void render(ProgressOverlay overlay)
	{
		BufferedImage canvas = new BufferedImage(300, 120, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		try
		{
			overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}
}

package com.actualafk;

import java.awt.Component;
import java.awt.Container;
import java.awt.Insets;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.swing.JLabel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ProgressPanelTest
{
	@Test
	public void canvasContextMenuTracksOverlayState() throws Exception
	{
		AtomicBoolean requestedState = new AtomicBoolean();
		SwingUtilities.invokeAndWait(() ->
		{
			ProgressPanel panel = new ProgressPanel();
			panel.setCanvasOverlayToggleAction(requestedState::set);

			assertEquals("Add to canvas", panel.getCanvasMenuText());
			panel.activateCanvasMenuItem();
			assertTrue(requestedState.get());

			panel.setCanvasOverlayVisible(true);
			assertEquals("Remove from canvas", panel.getCanvasMenuText());
			panel.activateCanvasMenuItem();
			assertFalse(requestedState.get());
		});
	}

	@Test
	public void outerPanelRetainsRuneLitePadding() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			ProgressPanel panel = new ProgressPanel();
			Insets insets = panel.getBorder().getBorderInsets(panel);

			assertEquals(new Insets(6, 6, 6, 6), insets);
		});
	}

	@Test
	public void runeLiteScrollPaneDoesNotPaintAnOuterBorder() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			ProgressPanel panel = new ProgressPanel();
			JScrollPane scrollPane = findScrollPane(panel.getWrappedPanel());

			assertNotNull(scrollPane);
			assertNull(scrollPane.getBorder());
			assertNull(scrollPane.getViewportBorder());
		});
	}

	@Test
	public void titleIncludesOrangeBetaLabel() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			ProgressPanel panel = new ProgressPanel();
			JLabel betaLabel = findLabel(panel.getWrappedPanel(), "BETA");

			assertNotNull(betaLabel);
			assertEquals(ColorScheme.BRAND_ORANGE, betaLabel.getForeground());
		});
	}

	@Test
	public void afkTickDurationsUseTheNominalGameTickLength()
	{
		assertEquals("0s", ProgressPanel.formatTickDuration(0));
		assertEquals("1m 00s", ProgressPanel.formatTickDuration(100));
		assertEquals("1h 00m 00s", ProgressPanel.formatTickDuration(6000));
		assertEquals("1d 00h 00m", ProgressPanel.formatTickDuration(144000));
	}

	@Test
	public void sessionAfkPercentageUsesObservedLoggedInTicks()
	{
		assertEquals("0.0%", ProgressPanel.formatPercentage(0, 0));
		assertEquals("25.0%", ProgressPanel.formatPercentage(25, 100));
		assertEquals("33.3%", ProgressPanel.formatPercentage(1, 3));
		assertEquals("100.0%", ProgressPanel.formatPercentage(200, 100));
	}

	@Test
	public void sidebarStatisticsRespectIndividualSettings() throws Exception
	{
		AtomicBoolean showSessionRate = new AtomicBoolean(true);
		AtomicBoolean showTotalTime = new AtomicBoolean(false);
		AfkConfig config = new AfkConfig()
		{
			@Override public boolean showPanelSessionXpPerHour() { return showSessionRate.get(); }
			@Override public boolean showPanelTotalTime() { return showTotalTime.get(); }
		};
		SwingUtilities.invokeAndWait(() ->
		{
			ProgressPanel panel = new ProgressPanel(config);
			assertTrue(panel.isTotalExperienceVisible());
			assertTrue(panel.isSessionExperiencePerHourVisible());
			assertTrue(panel.isLevelProgressVisible());
			assertFalse(panel.isStatisticVisible(PanelStatistic.TOTAL_TIME));

			showTotalTime.set(true);
			showSessionRate.set(false);
			panel.refreshStatisticVisibility();

			assertTrue(panel.isStatisticVisible(PanelStatistic.TOTAL_TIME));
			assertFalse(panel.isSessionExperiencePerHourVisible());
		});
	}

	@Test
	public void everyConfiguredStatisticIsRegisteredWithThePanel() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			ProgressPanel panel = new ProgressPanel();
			for (PanelStatistic statistic : PanelStatistic.values())
			{
				assertTrue(statistic.toString(), panel.isStatisticVisible(statistic));
			}
		});
	}

	@Test
	public void hiddenRowsCollapseAndEmptySessionHeadingDisappears() throws Exception
	{
		AfkConfig config = new AfkConfig()
		{
			@Override public boolean showPanelSessionAfkTicks() { return false; }
			@Override public boolean showPanelSessionAfkTime() { return false; }
			@Override public boolean showPanelSessionTotalTime() { return false; }
			@Override public boolean showPanelSessionIdlePercentage() { return false; }
			@Override public boolean showPanelSessionActivePercentage() { return false; }
			@Override public boolean showPanelSessionAfkXp() { return false; }
			@Override public boolean showPanelSessionXpPerHour() { return false; }
		};
		SwingUtilities.invokeAndWait(() ->
		{
			ProgressPanel panel = new ProgressPanel(config);
			assertFalse(panel.isSectionHeadingVisible("Session"));
			assertTrue(panel.isSectionHeadingVisible("Total"));
			assertTrue(panel.isSectionHeadingVisible("Streak"));
			assertEquals(26, panel.getDisplayedStatisticComponentCount());
		});
	}

	private static JScrollPane findScrollPane(Container container)
	{
		for (Component component : container.getComponents())
		{
			if (component instanceof JScrollPane)
			{
				return (JScrollPane) component;
			}
			if (component instanceof Container)
			{
				JScrollPane scrollPane = findScrollPane((Container) component);
				if (scrollPane != null)
				{
					return scrollPane;
				}
			}
		}
		return null;
	}

	private static JLabel findLabel(Container container, String text)
	{
		for (Component component : container.getComponents())
		{
			if (component instanceof JLabel && text.equals(((JLabel) component).getText()))
			{
				return (JLabel) component;
			}
			if (component instanceof Container)
			{
				JLabel label = findLabel((Container) component, text);
				if (label != null)
				{
					return label;
				}
			}
		}
		return null;
	}
}

package com.actualafk;

import java.util.HashMap;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ProgressStoreTest
{
	@Test
	public void lifetimeValuesRoundTripAndSessionValuesRestartAtZero()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		ProgressStore store = new ProgressStore(configuration);
		AfkProgress expected = new AfkProgress(100, 4, 8, 12, 250);

		store.save(expected);
		AfkProgress actual = store.load();

		assertEquals(100, actual.getTotalAfkXp());
		assertEquals(0, actual.getCurrentIdleStreakTicks());
		assertEquals(8, actual.getLongestIdleStreakTicks());
		assertEquals(0, actual.getSessionQualifyingTicks());
		assertEquals(250, actual.getTotalObservedTicks());
		assertEquals("2", configuration.values.get("formatVersion"));
		assertNull(configuration.values.get("currentIdleStreakTicks"));
		assertNull(configuration.values.get("sessionQualifyingTicks"));
		assertEquals(ProgressStore.LoadStatus.LOADED, store.getLoadStatus());
	}

	@Test
	public void missingValuesLoadAsZero()
	{
		AfkProgress progress = new ProgressStore(new InMemoryConfigurationStore()).load();

		assertEquals(0, progress.getTotalAfkXp());
		assertEquals(0, progress.getLongestIdleStreakTicks());
	}

	@Test
	public void malformedAndNegativeValuesLoadAsZero()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("formatVersion", "1");
		configuration.values.put("totalVirtualXp", "not-a-number");
		configuration.values.put("currentIdleStreakTicks", "-1");
		configuration.values.put("longestIdleStreakTicks", "8");
		configuration.values.put("sessionQualifyingTicks", "12");

		AfkProgress progress = new ProgressStore(configuration).load();

		assertEquals(0, progress.getTotalAfkXp());
		assertEquals(0, progress.getCurrentIdleStreakTicks());
		assertEquals(8, progress.getLongestIdleStreakTicks());
		assertEquals(0, progress.getSessionQualifyingTicks());
	}

	@Test
	public void unsupportedVersionLoadsDefaults()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("formatVersion", "3");
		configuration.values.put("totalVirtualXp", "100");

		ProgressStore store = new ProgressStore(configuration);
		assertEquals(0, store.load().getTotalAfkXp());
		assertEquals(ProgressStore.LoadStatus.UNSUPPORTED_VERSION, store.getLoadStatus());
		store.save(new AfkProgress(999, 0, 0, 0));
		assertEquals("100", configuration.values.get("totalVirtualXp"));
	}

	@Test
	public void missingMarkerWithDataIsNotOverwritten()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("totalVirtualXp", "100");
		ProgressStore store = new ProgressStore(configuration);

		assertEquals(0, store.load().getTotalAfkXp());
		assertEquals(ProgressStore.LoadStatus.INCOMPLETE, store.getLoadStatus());
		store.save(new AfkProgress(999, 0, 0, 0));
		assertEquals("100", configuration.values.get("totalVirtualXp"));
		assertNull(configuration.values.get("formatVersion"));
	}

	@Test
	public void transientReadFailureRefusesSave()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("formatVersion", "2");
		configuration.values.put("totalVirtualXp", "100");
		configuration.failReadsFor.add("longestIdleStreakTicks");
		ProgressStore store = new ProgressStore(configuration);

		assertEquals(100, store.load().getTotalAfkXp());
		assertEquals(ProgressStore.LoadStatus.READ_FAILED, store.getLoadStatus());
		store.save(new AfkProgress(999, 0, 0, 0));
		assertEquals("100", configuration.values.get("totalVirtualXp"));
	}

	@Test
	public void malformedFieldDefaultsWithoutPreventingValidFieldsFromLoading()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("formatVersion", "2");
		configuration.values.put("totalVirtualXp", "not-a-number");
		configuration.values.put("longestIdleStreakTicks", "8");
		configuration.values.put("totalObservedTicks", Long.toString(Long.MAX_VALUE));

		ProgressStore store = new ProgressStore(configuration);
		AfkProgress progress = store.load();

		assertEquals(0, progress.getTotalAfkXp());
		assertEquals(8, progress.getLongestIdleStreakTicks());
		assertEquals(Long.MAX_VALUE, progress.getTotalObservedTicks());
		assertEquals(ProgressStore.LoadStatus.LOADED, store.getLoadStatus());
	}

	@Test
	public void saveWritesFormatMarkerLast()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		ProgressStore store = new ProgressStore(configuration);

		store.save(new AfkProgress(42, 0, 7, 0));

		assertEquals("formatVersion", configuration.writes.get(configuration.writes.size() - 1));
	}

	@Test
	public void interruptedUpdateRemovesCommitMarkerAndProtectsPartialData()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		ProgressStore store = new ProgressStore(configuration);
		store.save(new AfkProgress(10, 0, 2, 0));
		configuration.failWritesFor.add("longestIdleStreakTicks");

		try
		{
			store.save(new AfkProgress(20, 0, 4, 0));
			assertTrue("expected simulated write failure", false);
		}
		catch (IllegalStateException expected)
		{
			assertEquals("simulated write failure", expected.getMessage());
		}

		ProgressStore reloadedStore = new ProgressStore(configuration);
		reloadedStore.load();
		assertEquals(ProgressStore.LoadStatus.INCOMPLETE, reloadedStore.getLoadStatus());
		assertNull(configuration.values.get("formatVersion"));
	}

	@Test
	public void versionOneDataMigratesWithKnownIdleTicksAsObservedBaseline()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("formatVersion", "1");
		configuration.values.put("totalVirtualXp", "100");

		AfkProgress progress = new ProgressStore(configuration).load();

		assertEquals(100, progress.getTotalAfkXp());
		assertEquals(100, progress.getTotalObservedTicks());
	}

	@Test
	public void resetRemovesOnlyProgressKeys()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		ProgressStore store = new ProgressStore(configuration);
		store.save(new AfkProgress(10, 1, 2, 3));
		configuration.values.put("unrelatedSetting", "keep");

		store.reset();

		assertEquals(0, new ProgressStore(configuration).load().getTotalAfkXp());
		assertEquals("keep", configuration.values.get("unrelatedSetting"));
	}

	@Test
	public void explicitResetAllowsSavingAfterUnsupportedVersion()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("formatVersion", "3");
		configuration.values.put("totalVirtualXp", "100");
		ProgressStore store = new ProgressStore(configuration);
		store.load();

		store.reset();
		store.save(new AfkProgress(5, 0, 0, 0));

		assertEquals(ProgressStore.LoadStatus.EMPTY, store.getLoadStatus());
		assertEquals("2", configuration.values.get("formatVersion"));
		assertEquals("5", configuration.values.get("totalVirtualXp"));
	}

	@Test
	public void unavailableProfileCannotBeOverwrittenWithDefaults()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("formatVersion", "1");
		configuration.values.put("totalVirtualXp", "280");
		configuration.available = false;

		ProgressStore store = new ProgressStore(configuration);
		store.save(new AfkProgress());
		store.reset();

		assertEquals("1", configuration.values.get("formatVersion"));
		assertEquals("280", configuration.values.get("totalVirtualXp"));
	}

	@Test
	public void progressLoadsAfterProfileBecomesAvailable()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		configuration.values.put("formatVersion", "1");
		configuration.values.put("totalVirtualXp", "280");
		configuration.available = false;
		ProgressStore store = new ProgressStore(configuration);

		assertFalse(store.isAvailable());
		configuration.available = true;

		assertTrue(store.isAvailable());
		assertEquals(280, store.load().getTotalAfkXp());
	}

	@Test
	public void progressCanBeSavedToAnExplicitPreviousProfile()
	{
		InMemoryConfigurationStore configuration = new InMemoryConfigurationStore();
		ProgressStore store = new ProgressStore(configuration);

		store.save(new AfkProgress(42, 0, 7, 0), "previous-profile");

		assertEquals("previous-profile", configuration.lastWrittenProfileKey);
		assertEquals("42", configuration.values.get("totalVirtualXp"));
		assertEquals("7", configuration.values.get("longestIdleStreakTicks"));
	}

	@Test
	public void runeLiteAdapterPassesGroupBeforeExplicitProfile()
	{
		RecordingConfigManagerAccess configManager = new RecordingConfigManagerAccess();
		ProgressStore store = new ProgressStore(new ProgressStore.RuneLiteConfigurationStore(configManager));

		store.save(new AfkProgress(42, 0, 7, 0), "previous-profile");

		assertEquals(ProgressStore.CONFIG_GROUP, configManager.lastSetGroup);
		assertEquals("previous-profile", configManager.lastSetProfile);
		assertEquals(ProgressStore.CONFIG_GROUP, configManager.lastUnsetGroup);
		assertEquals("previous-profile", configManager.lastUnsetProfile);
	}

	private static final class InMemoryConfigurationStore implements ProgressStore.ConfigurationStore
	{
		private final Map<String, String> values = new HashMap<>();
		private final List<String> writes = new ArrayList<>();
		private final List<String> failReadsFor = new ArrayList<>();
		private final List<String> failWritesFor = new ArrayList<>();
		private boolean available = true;
		private String lastWrittenProfileKey;

		@Override
		public boolean isAvailable()
		{
			return available;
		}

		@Override
		public String get(String key)
		{
			if (failReadsFor.contains(key))
			{
				throw new IllegalStateException("simulated read failure");
			}
			return values.get(key);
		}

		@Override
		public void set(String profileKey, String key, String value)
		{
			if (failWritesFor.contains(key))
			{
				throw new IllegalStateException("simulated write failure");
			}
			lastWrittenProfileKey = profileKey;
			writes.add(key);
			values.put(key, value);
		}

		@Override
		public void unset(String profileKey, String key)
		{
			values.remove(key);
		}
	}

	private static final class RecordingConfigManagerAccess implements ProgressStore.ConfigManagerAccess
	{
		private final Map<String, String> values = new HashMap<>();
		private String lastSetGroup;
		private String lastSetProfile;
		private String lastUnsetGroup;
		private String lastUnsetProfile;

		@Override
		public String getRSProfileKey()
		{
			return "current-profile";
		}

		@Override
		public String getRSProfileConfiguration(String groupName, String key)
		{
			return values.get(key);
		}

		@Override
		public void setRSProfileConfiguration(String groupName, String key, String value)
		{
			values.put(key, value);
		}

		@Override
		public void unsetRSProfileConfiguration(String groupName, String key)
		{
			values.remove(key);
		}

		@Override
		public void setConfiguration(String groupName, String profileKey, String key, String value)
		{
			lastSetGroup = groupName;
			lastSetProfile = profileKey;
			values.put(key, value);
		}

		@Override
		public void unsetConfiguration(String groupName, String profileKey, String key)
		{
			lastUnsetGroup = groupName;
			lastUnsetProfile = profileKey;
			values.remove(key);
		}
	}
}
